"""Independent, deliberately naive reference: enumerates every execution path.

Uses explicit per-thread buffer lists and a plain byte list for memory, i.e. a
completely different representation from main.py, so that representation bugs
show up.  Exponential in the number of instructions: only for tiny inputs.
"""
import json


def brute(request):
    mem0 = [int(b) & 0xFF for b in request['memory']]
    threads = request['threads']
    T = len(threads)
    programs = [[list(ins) for ins in prog] for prog in threads]
    outcomes = set()

    def load_val(t, addr, width, bufs, mem):
        val = 0
        for k in range(width):
            j = addr + k
            b = None
            for saddr, swidth, svalue in reversed(bufs[t]):   # youngest first
                if saddr <= j < saddr + swidth:
                    b = (svalue >> (8 * (j - saddr))) & 0xFF
                    break
            if b is None:
                b = mem[j]
            val |= b << (8 * k)
        return val

    def rec(pcs, bufs, mem, reads):
        enabled = []
        for t in range(T):
            prog = programs[t]
            if pcs[t] < len(prog):
                op = prog[pcs[t]][0]
                if op in ('store', 'load'):
                    enabled.append(('i', t))
                elif op in ('fence', 'xchg'):
                    if not bufs[t]:
                        enabled.append(('i', t))
                else:
                    raise ValueError(op)
            if bufs[t]:
                enabled.append(('d', t))

